diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-29 02:29:04.002817424 +0000
+++ b/csv.test.ts	2026-10-29 02:31:22.579485535 +0000
@@ -23,3 +23,102 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+function expected(input: string): string[][] | "SyntaxError" {
+  try {
+    return parseCsv(input);
+  } catch (e) {
+    if (e instanceof SyntaxError) return "SyntaxError";
+    throw e;
+  }
+}
+
+function streamed(input: string, cuts: number[]): string[][] | "SyntaxError" {
+  const bounds = [0, ...cuts, input.length];
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  try {
+    for (let k = 0; k + 1 < bounds.length; k++) rows.push(...s.push(input.slice(bounds[k], bounds[k + 1])));
+    rows.push(...s.end());
+  } catch (e) {
+    if (e instanceof SyntaxError) return "SyntaxError";
+    throw e;
+  }
+  return rows;
+}
+
+const inputs = [
+  "", "\uFEFF", "\uFEFFa", "\uFEFF\uFEFF", "a\uFEFF",
+  "a", "a,", ",", "\n", "a\n", "a\n\n", "\r", "a\r", "a\rb", "a\r\r\n", "\r\n\r\n", "a\r,b",
+  '"a"', '""', '""""', '"a""b"', '"a\r\nb",c\r\n', '"a"\r\n', '"a","b"\n"c"', 'x,"y"""',
+  '"a"b', '"a', '"a""', 'a"b', '"a"\r', '"a"\rb', 'a\r"',
+  'a,b\r\n"x,""y""",z\n',
+];
+
+test("any split into chunks gives the rows parseCsv gives", () => {
+  for (const input of inputs) {
+    const want = expected(input);
+    const n = input.length;
+    expect(streamed(input, [])).toEqual(want);
+    expect(streamed(input, Array.from({ length: n }, (_, k) => k + 1).slice(0, -1))).toEqual(want);
+    for (let a = 0; a <= n; a++) {
+      expect(streamed(input, [a])).toEqual(want);
+      for (let b = a; b <= n; b++) expect(streamed(input, [a, b])).toEqual(want);
+    }
+  }
+});
+
+test("empty chunks change nothing", () => {
+  for (const input of inputs) {
+    const s = new CsvStream();
+    const rows: string[][] = [];
+    const pieces = ["", ...input.split(""), ""];
+    try {
+      for (const p of pieces) rows.push(...s.push(p));
+      rows.push(...s.end());
+    } catch (e) {
+      expect(expected(input)).toBe("SyntaxError");
+      continue;
+    }
+    expect(rows).toEqual(expected(input) as string[][]);
+  }
+});
+
+test("rows come out as soon as their row end has arrived", () => {
+  const s = new CsvStream();
+  expect(s.push('"a\n')).toEqual([]);
+  expect(s.push('b"\n')).toEqual([["a\nb"]]);
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+});
+
+test("a row end split between chunks is still one row end", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\r\n")).toEqual([["a\r"]]);
+  expect(s.end()).toEqual([]);
+});
+
+test("a long input one character at a time parses in linear time", () => {
+  const input = '"' + "x,\n".repeat(60000) + '"\n' + "a,b\r\n".repeat(20000);
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of input) rows.push(...s.push(c));
+  rows.push(...s.end());
+  expect(rows).toEqual(parseCsv(input));
+});
+
+test("the end of input after a closing quote and \\r names the \\r, not an open field", () => {
+  expect(() => parseCsv('"a"\r')).toThrow('unexpected "\\r" after a closing quote');
+  const s = new CsvStream();
+  s.push('"a"\r');
+  expect(() => s.end()).toThrow('unexpected "\\r" after a closing quote');
+});
+
+test("once a call has thrown, every later push and end throws too", () => {
+  const s = new CsvStream();
+  expect(() => s.push('"a"b')).toThrow(SyntaxError);
+  expect(() => s.push("\n")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 02:29:04.002858467 +0000
+++ b/csv.ts	2026-10-29 02:31:20.247485397 +0000
@@ -50,3 +50,140 @@
   rows.push(row);
   return rows;
 }
+
+type State = "rowStart" | "fieldStart" | "unquoted" | "unquotedCR" | "quoted" | "quotedQuote" | "afterQuote" | "afterQuoteCR";
+
+/** Reads the same format as parseCsv from chunks of any size; each call's work depends only on that chunk. */
+export class CsvStream {
+  private started = false;
+  private offset = 0;
+  private state: State = "rowStart";
+  private row: string[] = [];
+  private field = "";
+  private failed = false;
+
+  push(chunk: string): string[][] {
+    const rows: string[][] = [];
+    try {
+      this.check();
+      let i = 0;
+      if (!this.started && chunk.length > 0) {
+        this.started = true;
+        if (chunk[0] === "﻿") {
+          i = 1;
+          this.offset++;
+        }
+      }
+      for (; i < chunk.length; i++) {
+        this.feed(chunk[i]!, rows);
+        this.offset++;
+      }
+    } catch (e) {
+      this.failed = true;
+      throw e;
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    const rows: string[][] = [];
+    try {
+      this.check();
+      switch (this.state) {
+        case "rowStart":
+          break;
+        case "unquotedCR":
+          this.field += "\r";
+          this.endRow(rows);
+          break;
+        case "quoted":
+          throw new SyntaxError("a quoted field is still open at the end of the input");
+        case "afterQuoteCR":
+          throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.offset - 1}`);
+        default:
+          this.endRow(rows);
+      }
+    } catch (e) {
+      this.failed = true;
+      throw e;
+    }
+    return rows;
+  }
+
+  /** Once a call has thrown, the input is rejected: every later call throws too. */
+  private check() {
+    if (this.failed) throw new SyntaxError("the input was rejected by an earlier call");
+  }
+
+  private pushField() {
+    this.row.push(this.field);
+    this.field = "";
+  }
+
+  private endRow(rows: string[][]) {
+    this.pushField();
+    rows.push(this.row);
+    this.row = [];
+    this.state = "rowStart";
+  }
+
+  private feed(c: string, rows: string[][]) {
+    switch (this.state) {
+      case "rowStart":
+      case "fieldStart":
+        if (c === '"') this.state = "quoted";
+        else if (c === ",") {
+          this.pushField();
+          this.state = "fieldStart";
+        } else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") this.state = "unquotedCR";
+        else {
+          this.field = c;
+          this.state = "unquoted";
+        }
+        break;
+      case "unquoted":
+        if (c === ",") {
+          this.pushField();
+          this.state = "fieldStart";
+        } else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") this.state = "unquotedCR";
+        else if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${this.offset}`);
+        else this.field += c;
+        break;
+      case "unquotedCR":
+        if (c === "\n") this.endRow(rows);
+        else {
+          this.field += "\r";
+          this.state = "unquoted";
+          this.feed(c, rows);
+        }
+        break;
+      case "quoted":
+        if (c === '"') this.state = "quotedQuote";
+        else this.field += c;
+        break;
+      case "quotedQuote":
+        if (c === '"') {
+          this.field += '"';
+          this.state = "quoted";
+        } else {
+          this.state = "afterQuote";
+          this.feed(c, rows);
+        }
+        break;
+      case "afterQuote":
+        if (c === ",") {
+          this.pushField();
+          this.state = "fieldStart";
+        } else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") this.state = "afterQuoteCR";
+        else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${this.offset}`);
+        break;
+      case "afterQuoteCR":
+        if (c === "\n") this.endRow(rows);
+        else throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.offset - 1}`);
+        break;
+    }
+  }
+}

