+const outside: Hit = { name: 'rm-outside', reason: 'recursive rm or find -delete/-exec outside the working directory' };
+
+function gitHit(argv: string[]): Hit | undefined {
+  let i = 1;
+  while (argv[i]?.startsWith('-')) i += gitValueOpts.has(argv[i]) ? 2 : 1;
+  const sub = argv[i];
+  const rest = argv.slice(i + 1);
+  if (sub === 'push' && rest.some((w) => forceLongs.some((n) => longFlag(w, n)) || shortGroup(w, 'fd') || /^[+:]/.test(w)))
+    return { name: 'force-push', reason: 'git push that rewrites or deletes remote refs' };
+  if (sub === 'reset' && rest.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards local changes' };
+  if (sub === 'clean' && rest.some((w) => w === '--force' || shortGroup(w, 'f')) && !rest.some((w) => w === '-n' || w === '--dry-run'))
+    return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+  return undefined;
+}
+
+function rmHit(argv: string[], cwd: string): Hit | undefined {
+  let recursive = false;
+  let dashDash = false;
+  const targets: string[] = [];
+  for (const w of argv.slice(1)) {
+    if (!dashDash && w === '--') dashDash = true;
+    else if (!dashDash && w.startsWith('-')) recursive ||= w === '--recursive' || shortGroup(w, 'rR');
+    else targets.push(w);
+  }
+  if (!recursive) return undefined;
+  if (targets.length === 0 || targets.some((t) => unresolvable(t) || !insideWorkspace(t, cwd) || sameDir(t, cwd))) return outside;
+  return undefined;
+}
+
+function findHit(argv: string[], cwd: string): Hit | undefined {
+  if (!argv.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  const starts: string[] = [];
+  for (const w of argv.slice(1)) {
+    if (w.startsWith('-')) break;
+    starts.push(w);
+  }
+  if (starts.length === 0) starts.push('.');
+  if (starts.some((p) => unresolvable(p) || !insideWorkspace(p, cwd))) return outside;
+  return undefined;
+}
+
 // Looks at one simple command's argv (already split, quotes removed) and returns a Hit when it must be denied.
 //
 // git (argv[0] may be a path such as /usr/bin/git). Global options before the subcommand are skipped; -C, -c,
@@ -36,5 +84,10 @@
 //
 // Anything else: undefined.
 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  const cmd = basename(argv[0]);
+  if (cmd === 'git') return gitHit(argv);
