+  m("a");
+  calls[0]!.d.resolve("a");
+  await tick();
+  expect(m.size).toBe(1);
+  t = 100;
+  expect(m.size).toBe(0);
+});
+
+test("a rejection is not kept: the next call runs fn again and waiters get the error", async () => {
+  const { fn, calls } = lookups();
+  const m = memo(fn, { ttlMs: 1000, max: 10 });
+  const first = m("k");
+  const second = m("k");
+  expect(calls).toHaveLength(1);
+  calls[0]!.d.reject(new Error("boom"));
