+import { expect, test } from "bun:test";
+import { distinctInWindow, type Event } from "./window";
+
+function naive(events: Event[], windowMs: number): number[] {
+  return events.map((e) => {
+    const keys = new Set<string>();
+    for (const other of events) if (other.t > e.t - windowMs && other.t <= e.t) keys.add(other.key);
+    return keys.size;
+  });
+}
+
+test("input order does not change the counts for each event", () => {
+  const events = [
+    { t: 8, key: "a" },
+    { t: 0, key: "a" },
+    { t: 20, key: "c" },
+    { t: 5, key: "b" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([2, 1, 1, 2]);
+});
+
+test("events with the same time are in each other's window", () => {
+  expect(distinctInWindow([{ t: 5, key: "a" }, { t: 5, key: "b" }], 10)).toEqual([2, 2]);
+  expect(distinctInWindow([{ t: 5, key: "b" }, { t: 1, key: "a" }], 10)).toEqual([2, 1]);
+});
+
+test("the window starts after t - windowMs and ends at t", () => {
+  expect(distinctInWindow([{ t: 0, key: "a" }, { t: 10, key: "b" }], 10)).toEqual([1, 1]);
+});
+
+test("floating-point rounding of t - windowMs is kept", () => {
+  expect(distinctInWindow([{ t: 1e20, key: "a" }], 1)).toEqual([0]);
+});
+
+test("a repeated key counts once", () => {
+  expect(distinctInWindow([{ t: 1, key: "a" }, { t: 2, key: "a" }], 10)).toEqual([1, 1]);
+});
+
+test("a non-finite or negative window is refused", () => {
+  for (const w of [NaN, Infinity, -1]) {
+    expect(() => distinctInWindow([{ t: 1, key: "a" }], w)).toThrow(RangeError);
+  }
+});
+
+test("a non-finite time names the first bad event", () => {
+  const bad = [{ t: 1, key: "a" }, { t: NaN, key: "b" }, { t: "x" as unknown as number, key: "c" }];
+  expect(() => distinctInWindow(bad, 10)).toThrow(TypeError);
+  expect(() => distinctInWindow(bad, 10)).toThrow("event 1");
+});
+
+test("the input array is not reordered", () => {
+  const events = [{ t: 8, key: "a" }, { t: 0, key: "b" }, { t: 5, key: "c" }];
+  distinctInWindow(events, 10);
+  expect(events.map((e) => e.t)).toEqual([8, 0, 5]);
+});
+
+test("matches the quadratic definition on random input", () => {
+  let seed = 42;
+  const rand = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
+  for (let round = 0; round < 300; round++) {
+    const n = Math.floor(rand() * 50);
+    const events = Array.from({ length: n }, () => ({
+      t: rand() < 0.5 ? Math.floor(rand() * 20) : rand() * 20,
+      key: "abcd"[Math.floor(rand() * 4)],
+    }));
+    const windowMs = rand() < 0.5 ? Math.floor(rand() * 10) + 1 : rand() * 10 + 0.001;
+    expect(distinctInWindow(events, windowMs)).toEqual(naive(events, windowMs));
+  }
+});
+
+test("200,000 events finish well under a second", () => {
+  const events = Array.from({ length: 200_000 }, (_, i) => ({
+    t: Math.floor(Math.random() * 1e7),
+    key: `k${i % 1000}`,
+  }));
+  const start = performance.now();
+  distinctInWindow(events, 10_000);
+  expect(performance.now() - start).toBeLessThan(1000);
+});
