diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/rules.test.ts b/test/rules.test.ts
--- a/test/rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/rules.test.ts	2026-10-29 02:42:43.751526026 +0000
@@ -0,0 +1,61 @@
+import { expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Prices: PEN 120, MUG 450, CAP 1200, TEE 1500, BAG 2200.
+
+test('exactly 10 units gets 5% off the line', () => {
+  // 1200 - 60 = 1140; shipping 800 (< 5000); tax 7% of 1940 = 135.8 -> 136; total 2076
+  expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+});
+
+test('9 units gets no bulk discount', () => {
+  // 1080; shipping 800; tax 7% of 1880 = 131.6 -> 132; total 2012
+  expect(totals(cart('US', [['PEN', 9]]))).toMatchObject({ subtotal: 1080, coupon: 0, shipping: 800, tax: 132, total: 2012 });
+});
+
+test('49 units gets 5% off, not the 10% tier', () => {
+  // 5880 - 294 = 5586; shipping 0 (>= 5000); tax 7% of 5586 = 391.02 -> 391; total 5977
+  expect(totals(cart('US', [['PEN', 49]]))).toMatchObject({ subtotal: 5586, shipping: 0, tax: 391, total: 5977 });
+});
+
+test('exactly 50 units gets 10% off the line', () => {
+  // 6000 - 600 = 5400; shipping 0 (>= 5000); tax 7% of 5400 = 378; total 5778
+  expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+});
+
+test('lines of the same sku are merged before bulk pricing', () => {
+  // 10 PEN in total -> 5% off: 1140
+  const t = totals(cart('US', [['PEN', 5], ['PEN', 5]]));
+  expect(t.lines.length).toBe(1);
+  expect(t.lines[0].quantity).toBe(10);
+  expect(t).toMatchObject({ subtotal: 1140, total: 2076 });
+});
+
+test('shipping threshold uses the subtotal after the coupon', () => {
+  // 4500 + 600 = 5100; SAVE10 takes 510 -> 4590 < 5000, so shipping 800
+  // tax 7% of 5390 = 377.3 -> 377; total 4590 + 800 + 377 = 5767
+  expect(totals(cart('US', [['TEE', 3], ['PEN', 5]], 'SAVE10'))).toMatchObject({
+    subtotal: 5100,
+    coupon: 510,
+    shipping: 800,
+    tax: 377,
+    total: 5767,
+  });
+});
+
+test('FLAT5 is applied before the shipping threshold check', () => {
+  // 5100 - 500 = 4600 < 5000, so shipping 800 (not free); tax 7% of 5400 = 378; total 5778
+  expect(totals(cart('US', [['TEE', 3], ['PEN', 5]], 'FLAT5'))).toMatchObject({
+    subtotal: 5100,
+    coupon: 500,
+    shipping: 800,
+    tax: 378,
+    total: 5778,
+  });
+});
+
+test('UK ships free from 4000', () => {
+  // 2200 + 1200 + 600 = 4000 >= 4000, so shipping 0; tax 20% of 4000 = 800; total 4800
+  expect(totals(cart('UK', [['BAG', 1], ['CAP', 1], ['PEN', 5]]))).toMatchObject({ subtotal: 4000, shipping: 0, tax: 800, total: 4800 });
+});

