diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/duration.extra.test.ts b/test/duration.extra.test.ts
--- a/test/duration.extra.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/duration.extra.test.ts	2026-10-29 02:43:33.020656839 +0000
@@ -0,0 +1,29 @@
+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration';
+
+test('parseDuration handles fractions, compound and spaced input', () => {
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('2d 4h')).toBe(187_200_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('  90s ')).toBe(90_000);
+  expect(parseDuration('1m30s')).toBe(90_000);
+  expect(parseDuration('0.0005s')).toBe(1);
+});
+
+test('parseDuration rejects malformed input, quoting it in the message', () => {
+  for (const bad of ['', '10', 'h', '-1s', '5 s', '1H', '1.s']) {
+    expect(() => parseDuration(bad)).toThrow(JSON.stringify(bad));
+  }
+});
+
+test('formatDuration uses the largest units, no zero parts', () => {
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+  expect(formatDuration(86_400_000)).toBe('1d');
+  expect(formatDuration(5_400_000)).toBe('1h30m');
+});
+
+test('formatDuration throws on negative input', () => {
+  expect(() => formatDuration(-1)).toThrow();
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/lru.extra.test.ts b/test/lru.extra.test.ts
--- a/test/lru.extra.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/lru.extra.test.ts	2026-10-29 02:44:44.903725424 +0000
@@ -0,0 +1,114 @@
+import { expect, test } from 'bun:test';
+import { LRU } from '../src/lru';
+
+function setup(capacity: number, ttl: number) {
+  let t = 0;
+  const log: [string, number, string][] = [];
+  const c = new LRU<string, number>(capacity, ttl, () => t);
+  c.onEvict = (k, v, r) => log.push([k, v, r]);
+  return { c, log, advance: (ms: number) => (t += ms), setTime: (ms: number) => (t = ms) };
+}
+
+test('capacity eviction logs the least recently used entry', () => {
+  const { c, log } = setup(2, 10_000);
+  c.set('a', 1);
+  c.set('b', 2);
+  c.set('c', 3);
+  expect(log).toEqual([['a', 1, 'capacity']]);
+  expect(c.keys()).toEqual(['c', 'b']);
+});
+
+test('a get hit refreshes recency', () => {
+  const { c, log } = setup(2, 10_000);
+  c.set('a', 1);
+  c.set('b', 2);
+  c.get('a');
+  c.set('c', 3);
+  expect(log).toEqual([['b', 2, 'capacity']]);
+  expect(c.keys()).toEqual(['c', 'a']);
+});
+
+test('expired entries are removed before a live one is evicted', () => {
+  const { c, log, setTime } = setup(2, 1000);
+  c.set('a', 1);
+  setTime(500);
+  c.set('b', 2);
+  setTime(1000);
+  c.set('c', 3);
+  expect(log).toEqual([['a', 1, 'expired']]);
+  expect(c.keys()).toEqual(['c', 'b']);
+});
+
+test('expired entries count toward capacity', () => {
+  const { c, log, setTime } = setup(2, 1000);
+  c.set('a', 1);
+  setTime(1000);
+  c.set('b', 2);
+  setTime(2000);
+  expect(c.size).toBe(0);
+  c.set('c', 3);
+  expect(log).toEqual([
+    ['a', 1, 'expired'],
+    ['b', 2, 'expired'],
+  ]);
+  expect(c.keys()).toEqual(['c']);
+});
+
+test('delete reports live, expired and missing keys', () => {
+  const { c, log, setTime } = setup(5, 1000);
+  c.set('a', 1);
+  expect(c.delete('a')).toBe(true);
+  expect(log).toEqual([['a', 1, 'delete']]);
+  c.set('b', 2);
+  setTime(1000);
+  expect(c.delete('b')).toBe(false);
+  expect(log[1]).toEqual(['b', 2, 'expired']);
+  expect(c.delete('zz')).toBe(false);
+  expect(log.length).toBe(2);
+});
+
+test('get of an expired entry logs once', () => {
+  const { c, log, setTime } = setup(5, 1000);
+  c.set('a', 1);
+  setTime(1000);
+  expect(c.get('a')).toBeUndefined();
+  expect(c.get('a')).toBeUndefined();
+  expect(log).toEqual([['a', 1, 'expired']]);
+});
+
+test('set on an existing key renews its ttl and recency without evicting', () => {
+  const { c, log, setTime } = setup(2, 1000);
+  c.set('a', 1);
+  setTime(900);
+  c.set('a', 2);
+  c.set('b', 3);
+  setTime(1500);
+  expect(c.get('a')).toBe(2);
+  expect(log).toEqual([]);
+});
+
+test('inserting into a full cache does not read the clock for every entry', () => {
+  const n = 20_000;
+  let t = 0;
+  let calls = 0;
+  const c = new LRU<number, number>(n, 1_000_000, () => {
+    calls++;
+    return t;
+  });
+  for (let i = 0; i < n; i++) c.set(i, i);
+  calls = 0;
+  for (let i = n; i < 2 * n; i++) c.set(i, i);
+  expect(c.size).toBe(n);
+  expect(calls).toBeLessThan(10 * n);
+});
+
+test('size and keys skip expired entries without removing them', () => {
+  const { c, log, setTime } = setup(5, 1000);
+  c.set('a', 1);
+  setTime(600);
+  c.set('b', 2);
+  setTime(1200);
+  expect(c.size).toBe(1);
+  expect(c.keys()).toEqual(['b']);
+  expect(log).toEqual([]);
+});
