+import { expect, test } from 'bun:test';
+import { slugify, uniqueSlug } from '../src/slug';
+
+test('slugify strips diacritics and expands special letters', () => {
+  expect(slugify('à ç ñ ź')).toBe('a-c-n-z');
+  expect(slugify('Straße')).toBe('strasse');
+  expect(slugify('Æsir Œuvre Ørsted Łódź Đặng')).toBe('aesir-oeuvre-orsted-lodz-dang');
+});
+
+test('slugify collapses separators and trims them from the ends', () => {
+  expect(slugify('--Hi!!  there--')).toBe('hi-there');
+  expect(slugify('!!!')).toBe('');
+  expect(slugify('A1 b2')).toBe('a1-b2');
+});
+
+test('slugify cuts at max on a dash, or at max when there is none', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('ab-cd-ef', 6)).toBe('ab-cd');
+  expect(slugify('ab-cdef', 4)).toBe('ab');
+  expect(slugify('abcdef', 3)).toBe('abc');
+  expect(slugify('ab-cd', 10)).toBe('ab-cd');
+});
+
+test('uniqueSlug returns the first free numbered variant', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2']))).toBe('post-3');
+});
